// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { Stat } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Finance/Stat)

figma.connect(Stat, FIGMA_NODE_URL, {
  props: {
    unit: figma.string('unit'),
    size: figma.enum('size', { 'sm': 'sm', 'md': 'md', 'lg': 'lg' }),
    countUp: figma.boolean('countUp'),
    padded: figma.boolean('padded'),
    border: figma.enum('border', { 'spotlight': 'spotlight', 'none': 'none', '1px': '1px' }),
  },
  example: ({ unit, size, countUp, padded, border }) => (
    <Stat unit={unit} size={size} countUp={countUp} padded={padded} border={border}></Stat>
  ),
});
